style.css:
/* Change the background color of ChatGPT */
body {
  background-color: #f0f8ff !important;  /* Light blue background */
}

/* Change the chat area background */
div[data-id="chat-container"] {
  background-color: #f5f5f5 !important;  /* Light gray background */
}

/* Optional: Add a background image to the chat container */
div[data-id="chat-container"] {
  background-image: url('https://i.ytimg.com/vi/FZJS2rSHCsU/maxresdefault.jpg') !important;
  background-size: cover !important;
  background-position: center !important;
}

/* Optional: Apply a gradient to the chat area */
div[data-id="chat-container"] {
  background: linear-gradient(to right, #ff7e5f, #feb47b) !important; /* Gradient background */
}
